// =====================================================================
//  CONFIG  —  the only node you should need to edit.
//  The same Config node is used in all four workflows. Edit it once,
//  then copy/paste the node into the other three so they stay in sync.
//
//  WHY a Code node instead of a "Set" node: it lets every setting carry
//  a comment explaining what it does, and it can hold lists and objects.
// =====================================================================

const config = {
  // ---------- ACCOUNT ----------
  // Google Ads customer ID of the CLIENT account, digits only (no dashes).
  customer_id: '1234567890',
  // Your manager (MCC) account ID, digits only. Required when you reach the
  // client account through a manager account (the normal agency setup).
  login_customer_id: '0987654321',
  // Developer token from Google Ads > Tools > API Center (in the MCC).
  // Better: store it as an n8n Variable and use $vars.GOOGLE_ADS_DEV_TOKEN.
  developer_token: 'PASTE_DEVELOPER_TOKEN_HERE',
  // Google ships a new API version roughly monthly; each major version lives
  // about a year. If requests start failing with "version not found",
  // bump this (v25 is supported into Aug 2027).
  api_version: 'v25',
  account_timezone: 'America/Los_Angeles',
  currency: 'USD',

  // ---------- SAFETY SWITCHES ----------
  // DRY RUN = true: every change is sent with validateOnly, so Google CHECKS
  // it but changes nothing. Leave this on for the first 1–2 weeks and read
  // the logs. Flip to false only once the proposals look right to you.
  dry_run: true,
  approver_email: 'you@example.com',
  // Shared secret for runs started from the Blue Market Ads app.
  // Must match N8N_WEBHOOK_SECRET in Vercel.
  webhook_secret: 'PASTE_THE_SAME_SECRET_AS_VERCEL',
  // Hard limits the robot can never exceed, no matter what the math says.
  max_bid_increase_pct: 15,      // per run, per keyword
  max_bid_decrease_pct: 25,      // per run, per keyword
  max_cpc_ceiling: 25.00,        // absolute max bid in dollars
  min_cpc_floor: 0.50,
  max_budget_change_pct: 25,     // per run, per budget
  max_changes_per_run: 40,       // stops a bad run from doing 500 edits

  // ---------- BUSINESS GOALS (Firm Media baseline) ----------
  monthly_budget_total: 3000,    // client's monthly ad budget, in dollars
  target_cpa: 250,               // baseline cost per lead
  // Campaigns whose name contains a key get their own CPA target.
  // High-value procedures can afford more per lead; low-margin ones less.
  cpa_overrides: {
    'All-on-4': 600,
    'Implant': 450,
    'Cleaning': 120,
  },
  target_ctr: 0.07,              // 7% CTR benchmark
  call_min_seconds: 60,          // calls shorter than this are not leads
  // Bid strategy ladder thresholds (conversions in last 30 days)
  conv_for_max_conversions: 15,
  conv_for_target_cpa: 30,

  // ---------- DECISION THRESHOLDS ----------
  // How much a keyword may spend with zero conversions before action.
  // Expressed as a multiple of the campaign's target CPA.
  zero_conv_reduce_at: 1.0,      // lower its bid
  zero_conv_pause_at: 1.5,       // propose pausing it
  min_impr_for_ctr_check: 200,
  min_impr_for_qs_check: 100,
  odd_penny_bids: true,          // $12.00 -> $12.01 (tie-breaker habit)

  // ---------- AI SEARCH-TERM REVIEW ----------
  anthropic_model: 'claude-sonnet-5-5',
  // Tell Claude what the business sells so it can judge search intent.
  business_context:
    'Dental/periodontal practice. Sells: dental implants, All-on-4, gum ' +
    'grafting, periodontal treatment, cleanings. Wants new-patient ' +
    'consultations in the local service area. Does NOT want job seekers, ' +
    'students, DIY/home remedy seekers, or people looking for free care.',
  // Search terms containing these are always proposed as negatives.
  negative_seed_terms: [
    'job', 'jobs', 'career', 'careers', 'salary', 'hiring', 'school',
    'course', 'training', 'certification', 'free', 'diy', 'home remedy',
    'reddit', 'youtube', 'wikipedia', 'pdf', 'definition', 'meaning',
    'cartoon', 'clipart',
  ],

  // ---------- GOOGLE SHEET (change log + lead evaluation) ----------
  // One spreadsheet with two tabs: "Change Log" and "Leads".
  sheet_url: 'https://docs.google.com/spreadsheets/d/PASTE_SHEET_ID/edit',
  log_sheet_tab: 'Change Log',
  lead_sheet_tab: 'Leads',

  // ---------- OFFLINE REVENUE (Workflow 4) ----------
  // Map each lead stage in the sheet to a conversion action ID
  // (Google Ads > Goals > Conversions > click the action > ID in the URL "ctId=").
  // Workflow 3 can create these three actions for you.
  stage_to_conversion_action: {
    'Qualified Lead': '111111111',
    'Booked Consult': '222222222',
    'Closed - Revenue': '333333333',
  },
  // Offset of the sheet's timestamps from UTC (PDT = -07:00, PST = -08:00).
  sheet_utc_offset: '-07:00',
};

// ---------- GAQL QUERIES (Google Ads Query Language) ----------
// Think of these as SQL for your ad account. You rarely need to edit them.
config.queries = {
  // Whole-account spend this month — includes paused/removed campaigns,
  // because that money counts against the client's budget too.
  account_mtd: `
    SELECT metrics.cost_micros, metrics.conversions
    FROM customer
    WHERE segments.date DURING THIS_MONTH`,
  campaigns_mtd: `
    SELECT campaign.id, campaign.name, campaign.status,
           campaign.advertising_channel_type, campaign.bidding_strategy_type,
           campaign.target_spend.cpc_bid_ceiling_micros,
           campaign_budget.resource_name, campaign_budget.amount_micros,
           campaign_budget.explicitly_shared,
           metrics.cost_micros, metrics.clicks, metrics.impressions,
           metrics.conversions, metrics.conversions_value,
           metrics.search_impression_share,
           metrics.search_budget_lost_impression_share,
           metrics.search_rank_lost_impression_share, metrics.average_cpc
    FROM campaign
    WHERE segments.date DURING THIS_MONTH AND campaign.status = 'ENABLED'`,
  campaigns_30d: `
    SELECT campaign.id, metrics.cost_micros, metrics.clicks,
           metrics.conversions, metrics.conversions_value
    FROM campaign
    WHERE segments.date DURING LAST_30_DAYS AND campaign.status = 'ENABLED'`,
  campaigns_today: `
    SELECT campaign.id, campaign.name, campaign_budget.resource_name,
           campaign_budget.amount_micros, metrics.cost_micros,
           metrics.conversions, metrics.clicks
    FROM campaign
    WHERE segments.date DURING TODAY AND campaign.status = 'ENABLED'`,
  keywords_30d: `
    SELECT campaign.id, campaign.name, ad_group.id, ad_group.name,
           ad_group_criterion.resource_name, ad_group_criterion.criterion_id,
           ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type,
           ad_group_criterion.cpc_bid_micros,
           ad_group_criterion.effective_cpc_bid_micros,
           ad_group_criterion.quality_info.quality_score,
           ad_group_criterion.quality_info.creative_quality_score,
           ad_group_criterion.quality_info.post_click_quality_score,
           ad_group_criterion.quality_info.search_predicted_ctr,
           metrics.impressions, metrics.clicks, metrics.cost_micros,
           metrics.conversions, metrics.ctr, metrics.average_cpc,
           metrics.search_rank_lost_impression_share
    FROM keyword_view
    WHERE segments.date DURING LAST_30_DAYS
      AND ad_group_criterion.status = 'ENABLED'
      AND ad_group.status = 'ENABLED' AND campaign.status = 'ENABLED'`,
  search_terms_30d: `
    SELECT campaign.id, campaign.name, ad_group.id,
           search_term_view.search_term, search_term_view.status,
           metrics.impressions, metrics.clicks, metrics.cost_micros,
           metrics.conversions
    FROM search_term_view
    WHERE segments.date DURING LAST_30_DAYS AND metrics.clicks > 0
    ORDER BY metrics.cost_micros DESC
    LIMIT 400`,
  conversion_actions: `
    SELECT conversion_action.resource_name, conversion_action.id,
           conversion_action.name, conversion_action.status,
           conversion_action.type, conversion_action.category,
           conversion_action.primary_for_goal,
           conversion_action.counting_type,
           conversion_action.phone_call_duration_seconds,
           conversion_action.value_settings.default_value,
           conversion_action.click_through_lookback_window_days
    FROM conversion_action
    WHERE conversion_action.status != 'REMOVED'`,
  conversions_by_action_14d: `
    SELECT segments.conversion_action, segments.conversion_action_name,
           metrics.all_conversions
    FROM customer
    WHERE segments.date DURING LAST_14_DAYS`,
  customer_settings: `
    SELECT customer.id, customer.descriptive_name,
           customer.auto_tagging_enabled,
           customer.conversion_tracking_setting.enhanced_conversions_for_leads_enabled,
           customer.conversion_tracking_setting.accepted_customer_data_terms
    FROM customer`,
};

// ---------- STARTED FROM THE APP? ----------
// When the Blue Market Ads app starts this workflow, it sends the account
// to work on. The secret check stops anyone else from triggering it.
const body = $input.first()?.json?.body;
if (body && typeof body === 'object' && body.customer_id) {
  if (!config.webhook_secret || body.secret !== config.webhook_secret) {
    throw new Error('Webhook secret does not match. Run refused.');
  }
  config.customer_id = String(body.customer_id).replace(/\D/g, '');
  config.login_customer_id = String(body.login_customer_id || body.customer_id).replace(/\D/g, '');
  config.started_by = body.requested_by || 'Blue Market Ads app';
  config.account_name = body.account_name || '';
}

return [{ json: config }];

// =====================================================================
//  CONVERSION TRACKING AUDIT + SETUP
//
//  WHY this matters more than anything else in the system: every bid,
//  pause and budget decision is based on "conversions". If tracking
//  counts robocalls, double-counts forms, or silently breaks, the
//  optimizer confidently makes the WRONG changes. Garbage in, garbage out.
//
//  Checks run weekly. Fixes are only proposed in the email unless
//  auto_fix_conversion_settings is turned on below.
// =====================================================================

const cfg = $('Config').first().json;
const AUTO_FIX = false;   // set true to let this workflow apply the fixes
const actions = $('Get Conversion Actions').first().json.results || [];
const recent = $('Get Conversions by Action (14d)').first().json.results || [];
const cust = ($('Get Account Settings').first().json.results || [])[0]?.customer || {};
const cid = cfg.customer_id;

const issues = [], ok = [], fixes = [], fixSummaries = [];
const recentCount = {};
for (const r of recent) {
  const name = r.segments?.conversionActionName;
  recentCount[name] = (recentCount[name] || 0) + Number(r.metrics?.allConversions || 0);
}

// ---------- account-level settings ----------
if (cust.autoTaggingEnabled === false) {
  issues.push('AUTO-TAGGING IS OFF. Without it there is no gclid on clicks, so offline ' +
    'revenue (Workflow 4) cannot be matched to ads. Turn on: Admin > Account settings > Auto-tagging.');
} else ok.push('Auto-tagging on');

if (!cust.conversionTrackingSetting?.enhancedConversionsForLeadsEnabled) {
  issues.push('Enhanced conversions for leads is OFF. It matches form leads to ads using a ' +
    'hashed email/phone, recovering conversions that cookies miss (iOS, consent banners). ' +
    'Turn on in Goals > Settings and accept the customer data terms.');
}

// ---------- per conversion action ----------
const enabled = actions.map((r) => r.conversionAction).filter((a) => a.status === 'ENABLED');
const primary = enabled.filter((a) => a.primaryForGoal);
if (enabled.length === 0) issues.push('NO ENABLED CONVERSION ACTIONS. The account is bidding blind.');

const callTypes = ['AD_CALL', 'WEBSITE_CALL'];
const leadCategories = ['SUBMIT_LEAD_FORM', 'PHONE_CALL_LEAD', 'CONTACT', 'BOOK_APPOINTMENT',
  'QUALIFIED_LEAD', 'CONVERTED_LEAD', 'REQUEST_QUOTE', 'SIGNUP'];

for (const a of enabled) {
  // Firm Media rule: only calls of 60+ seconds count as leads.
  if (callTypes.includes(a.type) && Number(a.phoneCallDurationSeconds || 0) < cfg.call_min_seconds) {
    issues.push(`"${a.name}" counts calls of ${a.phoneCallDurationSeconds || 0}s+. ` +
      `Robocalls and hang-ups are being counted as leads. Should be ${cfg.call_min_seconds}s.`);
    fixes.push({ update: { resourceName: a.resourceName,
      phoneCallDurationSeconds: String(cfg.call_min_seconds) }, updateMask: 'phoneCallDurationSeconds' });
    fixSummaries.push(`"${a.name}": call length → ${cfg.call_min_seconds}s`);
  }
  // One person filling a form twice is one lead, not two.
  if (leadCategories.includes(a.category) && a.countingType === 'MANY_PER_CLICK') {
    issues.push(`"${a.name}" counts EVERY conversion per click. For leads, one person = one ` +
      `lead; this inflates conversions and makes CPA look better than it is.`);
    fixes.push({ update: { resourceName: a.resourceName, countingType: 'ONE_PER_CLICK' },
      updateMask: 'countingType' });
    fixSummaries.push(`"${a.name}": counting → One per click`);
  }
  // Silent tags: a primary action that recorded nothing in 14 days.
  if (a.primaryForGoal && !recentCount[a.name] && a.type !== 'UPLOAD_CLICKS') {
    issues.push(`"${a.name}" is PRIMARY but recorded 0 conversions in 14 days. The tag may ` +
      `be broken (check with Google Tag Assistant) — or the campaign truly got no leads.`);
  }
}

// Double counting: same lead tracked by the Ads tag AND a GA4 import.
const ga4 = primary.filter((a) => (a.type || '').startsWith('GOOGLE_ANALYTICS_4'));
const adsTags = primary.filter((a) => a.type === 'WEBPAGE' || a.type === 'WEBPAGE_CODELESS');
if (ga4.length && adsTags.length) {
  issues.push(`Possible DOUBLE COUNTING: ${ga4.length} GA4-imported and ${adsTags.length} ` +
    `Google Ads-tag actions are both PRIMARY. If they track the same form, each lead counts ` +
    `twice. Keep one as primary and set the other to secondary.`);
}

if (!enabled.some((a) => a.type === 'AD_CALL')) {
  issues.push('No "Calls from ads" conversion action. Calls from call assets are not being ' +
    'counted. Create one: Goals > New conversion action > Phone calls > Calls from ads, ' +
    `${cfg.call_min_seconds}s minimum.`);
}

// ---------- SETUP: offline lead-stage actions for Workflow 4 ----------
// These receive uploads from the Lead Evaluation Sheet. Created as
// SECONDARY so they report revenue without changing how bidding works yet.
const stageCategory = { 'Qualified Lead': 'QUALIFIED_LEAD', 'Booked Consult': 'BOOK_APPOINTMENT',
  'Closed - Revenue': 'CONVERTED_LEAD' };
const names = new Set(actions.map((r) => r.conversionAction.name));
for (const stage of Object.keys(cfg.stage_to_conversion_action || {})) {
  const name = `Offline - ${stage}`;
  if (names.has(name)) { ok.push(`"${name}" exists`); continue; }
  issues.push(`Missing offline stage action "${name}" (needed for revenue/ROAS import).`);
  fixes.push({ create: {
    name, type: 'UPLOAD_CLICKS', status: 'ENABLED',
    category: stageCategory[stage] || 'QUALIFIED_LEAD',
    countingType: 'ONE_PER_CLICK', primaryForGoal: false,
    clickThroughLookbackWindowDays: '90',   // consult sales cycles are long
    valueSettings: { defaultValue: 0, alwaysUseDefaultValue: false },
  } });
  fixSummaries.push(`Create "${name}" (secondary, 90-day window)`);
}

const body = [
  `CONVERSION TRACKING AUDIT — ${cust.descriptiveName || cid}`,
  '',
  issues.length ? `ISSUES (${issues.length})` : 'NO ISSUES FOUND',
  ...issues.map((i) => '• ' + i),
  '',
  `Primary actions (what bidding optimizes for): ${primary.map((a) => a.name).join(', ') || 'none'}`,
  `14-day counts: ${Object.entries(recentCount).map(([k, v]) => `${k}: ${v.toFixed(0)}`).join(' | ') || 'none'}`,
  '',
  fixSummaries.length
    ? (AUTO_FIX ? `FIXES ${cfg.dry_run ? 'VALIDATED (dry run)' : 'APPLIED'}:\n` : 'FIXES AVAILABLE (set AUTO_FIX = true in the audit node to apply):\n')
      + fixSummaries.map((f) => '  - ' + f).join('\n')
    : '',
  '',
  'After creating the offline actions, copy their IDs into Config > stage_to_conversion_action.',
].join('\n');

const requests = AUTO_FIX && fixes.length ? [{
  url: `https://googleads.googleapis.com/${cfg.api_version}/customers/${cid}/conversionActions:mutate`,
  body: { operations: fixes, partialFailure: true, validateOnly: cfg.dry_run === true },
  endpoint: 'conversionActions:mutate', summaries: fixSummaries,
}] : [];

return [{ json: { subject: `[Conversion Audit] ${issues.length} issue(s)`, body, requests } }];

// =====================================================================
//  BUILD API REQUESTS — turns the list of planned requests into one n8n
//  item per request, so the HTTP node below runs once for each.
//  If there are no changes, returning [] ends the workflow quietly.
// =====================================================================
const { requests } = $('Audit Tracking').first().json;
return (requests || []).map((r) => ({ json: r }));

// =====================================================================
//  LOG RESULTS — one spreadsheet row per change, so you have a full
//  history of what the system did, when, and whether Google accepted it.
// =====================================================================

const cfg = $('Config').first().json;
const requests = $('Build API Requests').all();
const responses = $input.all();
const rows = [];
const now = new Date().toISOString();

requests.forEach((req, i) => {
  const res = responses[i]?.json || {};
  const results = res.results || [];
  const httpError = res.error ? (res.error.message || JSON.stringify(res.error)).slice(0, 300) : '';
  // With partialFailure, failed operations come back as empty {} results.
  const pfErrors = (res.partialFailureError?.details || [])
    .flatMap((d) => d.errors || []).map((e) => e.message);

  req.json.summaries.forEach((summary, j) => {
    const ok = !httpError && results[j] && Object.keys(results[j]).length > 0;
    rows.push({ json: {
      timestamp: now,
      mode: cfg.dry_run ? 'DRY RUN' : 'LIVE',
      customer_id: cfg.customer_id,
      endpoint: req.json.endpoint,
      change: summary,
      status: httpError ? 'ERROR' : (ok || cfg.dry_run && !pfErrors.length ? 'OK' : 'FAILED'),
      detail: httpError || (ok ? (results[j].resourceName || '') : (pfErrors.shift() || '')),
    } });
  });
});
return rows;
